import * as CustomCode from '../CustomCode';

const getNotificationToken = async Variables => {
  const handleRegistrationError = errorMessage => {
    alert(errorMessage);
    throw new Error(errorMessage);
  };

  const isDevice =
    CustomCode.Device.isDevice && CustomCode.Platform.OS !== 'web'; // && CustomCode.ExpoConstants;

  if (isDevice && Variables.enableNotifications) {
    var projId;

    try {
      projId =
        CustomCode?.ExpoConstants?.expoConfig?.extra?.eas?.projectId ??
        CustomCode?.ExpoConstants?.easConfig?.projectId;

      if (!projId) handleRegistrationError('Project ID not found');

      console.log(`getNotificationToken] projectId: '${projId}'`);

      const expoPushToken =
        await CustomCode.ExpoNotifications.getExpoPushTokenAsync({
          // experienceId: '@digicard/dss',
          // applicationId: '@digicard/dss',      // la doc no es clara respecto de como debe llamarse este parametro
          projectId: projId,
        });
      console.log(`expoPushToken: ${JSON.stringify(expoPushToken, undefined, 2)}`);

      return expoPushToken;
    } 
    catch (e) {
      handleRegistrationError(
        `${e}, projectId: '${projId}'`
      );
    }
  }

  return { data: '' };
};

export default getNotificationToken;
