import * as GlobalFunctions from '../custom-files/GlobalFunctions';

const openRequest = (item, navigation, attachsReadOnly) => {
  const params = {
    record: item,
    readOnly: true,
    attachsReadOnly: attachsReadOnly,
  };

  // console.log(GlobalFunctions.jlog({item}));
  // console.log(GlobalFunctions.jlog({params}));

  switch (item.req_type) {
    case 'vac':
      navigation.push('Main', {
        screen: 'SolicitudVacacionesScreen',
        params: params,
      });
      break;

    case 'epp':
      navigation.push('Main', {
        screen: 'SolicitudEPPScreen',
        params: params,
      });
      break;

    case 'ctu':
      navigation.push('Main', {
        screen: 'SolicitudCambioDeTurnoScreen',
        params: params,
      });
      break;

    case 'pya':
      navigation.push('Main', {
        screen: 'SolicitudPermisoAusenciaScreen',
        params: params,
      });
      break;

    case 'rys':
      navigation.push('Main', {
        screen: 'SolicitudRetiroAnticipadoScreen',
        params: params,
      });
      break;
  }
};

export default openRequest;
