const GetConceptsList = (Variables, reqType) => {
  const conceptsToPickerOptions = (concepts, rtype) => {
    const con_type = (rtype ?? 'pya') == 'rys' ? 'hs' : 'di';

    const options = concepts
      .filter(c => c.con_type === con_type)
      .map(c => {
        return { label: c.con_name, value: c.con_id, ...c };
      });

    return options;
  };

  const conceptsList = Variables['ConceptsList'];
  return conceptsToPickerOptions(conceptsList, reqType);
};

export default GetConceptsList;
