const GetReasonsList = (Variables, reqType) => {
  const reasons2PickerOptions = (reasons, rtype) => {
    return reasons
      .filter(r => r.rea_type === rtype ?? 'pya')
      .map(r => {
        return { label: r.rea_name, value: r.rea_id };
      });
  };

  const reasonsList = Variables['ReasonsList'];
  return reasons2PickerOptions(reasonsList, reqType);
};

export default GetReasonsList;
