import React from 'react';
import {
  Button,
  Container,
  IconButton,
  ScreenContainer,
  TextField,
  Touchable,
  withTheme,
} from '@draftbit/ui';
import { useIsFocused } from '@react-navigation/native';
import { Image, Text, View } from 'react-native';
import { KeyboardAwareScrollView } from 'react-native-keyboard-aware-scroll-view';
import * as CustomCode from '../CustomCode';
import * as DcSSApi from '../apis/DcSSApi.js';
import * as GlobalVariables from '../config/GlobalVariableContext';
import Images from '../config/Images';
import passEncrypt from '../global-functions/passEncrypt';
import palettes from '../themes/palettes';
import * as Utils from '../utils';
import Breakpoints from '../utils/Breakpoints';
import * as StyleSheet from '../utils/StyleSheet';
import imageSource from '../utils/imageSource';
import useWindowDimensions from '../utils/useWindowDimensions';

const defaultProps = { selfChanged: false };

const CambioContrasenaScreen = props => {
  const { theme, navigation } = props;
  const dimensions = useWindowDimensions();
  const Constants = GlobalVariables.useValues();
  const Variables = Constants;
  const setGlobalVariableValue = GlobalVariables.useSetValue();
  const [SHOW_CUIL_ERROR, setSHOW_CUIL_ERROR] = React.useState(false);
  const [SHOW_EMAIL_ERROR, setSHOW_EMAIL_ERROR] = React.useState(false);
  const [SHOW_PASSWORD_ERROR, setSHOW_PASSWORD_ERROR] = React.useState(false);
  const [SHOW_PASSWORD_MISMATCH_ERROR, setSHOW_PASSWORD_MISMATCH_ERROR] =
    React.useState(false);
  const [cuil, setCuil] = React.useState('');
  const [email, setEmail] = React.useState('');
  const [errorMessage, setErrorMessage] = React.useState('');
  const [loading, setLoading] = React.useState(false);
  const [password, setPassword] = React.useState('');
  const [password_copy, setPassword_copy] = React.useState('');
  const [showPasswordHint, setShowPasswordHint] = React.useState(false);
  const extractError = body => {
    if (body.error) {
      if (body.error.details && body.error.details.length) {
        return `${body.error.details[0].path.substring(1)} ${
          body.error.details[0].message
        }`;
      }
      return body.error.message;
    }
    return '';
  };

  const validate = (value, regex, target_var) => {
    const invalid = !regex.test(value);
    console.log(`Value: ${value} Valid: ${!invalid}`);

    // setGlobalVariable({ key: target_var, value: invalid });
    target_var(invalid);

    return invalid;
  };

  const passwordCheck = password => {
    // De 8 a 100 cars, debe contener  1 mayúscula, 1 minúscula y 2 dígitos
    return validate(
      password,
      /^(?=.*[a-z])(?=.*[A-Z])(?=(.*\d){2,})[A-Za-z\d@$!%*?&]{8,100}$/,
      setSHOW_PASSWORD_ERROR
    );
  };

  const passwordCopyCheck = (passwordCopy, password) => {
    const invalid = password !== passwordCopy;

    console.log(
      `PasswordMismatch: ${invalid}, password: [${password}[], passwordCopy: [${passwordCopy}]`
    );
    // setGlobalVariable({ key: 'SHOW_PASSWORD_MISMATCH_ERROR', value: invalid });
    setSHOW_PASSWORD_MISMATCH_ERROR(invalid);

    return invalid;
  };
  // ======================== Inline Code ========================
  // to use a global variable inside the component logic
  const globalVariables = CustomCode.useValues();
  // to update or modify the value of a global variable
  const setGlobalVariable = CustomCode.useSetValue();
  // =================== End  Inline Code ========================
  const dcSSCambioClavePATCH = DcSSApi.useCambioClavePATCH();
  const dcSSEmployeeTokenPATCH = DcSSApi.useEmployeeTokenPATCH();
  const isFocused = useIsFocused();
  React.useEffect(() => {
    try {
      if (!isFocused) {
        return;
      }
      setCuil('');
      setEmail('');
      setPassword('');
      setPassword_copy('');
      setGlobalVariableValue({
        key: 'SHOW_CUIL_ERROR',
        value: '',
      });
      setGlobalVariableValue({
        key: 'SHOW_EMAIL_ERROR',
        value: '',
      });
      setGlobalVariableValue({
        key: 'SHOW_PASSWORD_ERROR',
        value: '',
      });
      setGlobalVariableValue({
        key: 'SHOW_PASSWORD_MISMATCH_ERROR',
        value: '',
      });
    } catch (err) {
      console.error(err);
    }
  }, [isFocused]);

  return (
    <ScreenContainer
      scrollable={false}
      hasSafeArea={true}
      style={StyleSheet.applyWidth(
        { backgroundColor: theme.colors.background.brand, height: '100%' },
        dimensions.width
      )}
    >
      <CustomCode.LoadingOverlay
        {...props}
        visible={loading}
        action={'connecting'}
      />
      {/* PasswordHintView */}
      <>
        {!showPasswordHint ? null : (
          <View
            style={StyleSheet.applyWidth(
              {
                alignItems: 'center',
                backgroundColor: palettes['App Modern'].Tooltip,
                height: '18%',
                justifyContent: 'center',
                left: '20%',
                opacity: 1,
                position: 'absolute',
                top: '50%',
                width: '65%',
                zIndex: 1,
              },
              dimensions.width
            )}
          >
            <Text
              accessible={true}
              selectable={false}
              style={StyleSheet.applyWidth(
                {
                  color: theme.colors.text.strong,
                  marginLeft: 5,
                  marginRight: 5,
                  marginTop: 5,
                },
                dimensions.width
              )}
            >
              {
                'Longitud: 8 a 100 cars\nAl menos una letra mayúscula\nAl menos una letra minúscula\nAl menos 2 dígitos\nNo debe contener espacios'
              }
            </Text>
          </View>
        )}
      </>
      <KeyboardAwareScrollView
        keyboardShouldPersistTaps={'never'}
        showsVerticalScrollIndicator={true}
        viewIsInsideTabBar={false}
        enableAutomaticScroll={true}
        enableOnAndroid={true}
        enableResetScrollToCoords={true}
        extraHeight={200}
        style={StyleSheet.applyWidth({ height: '100%' }, dimensions.width)}
      >
        <View
          style={StyleSheet.applyWidth(
            {
              alignContent: 'space-around',
              alignItems: 'center',
              alignSelf: 'center',
              justifyContent: 'space-around',
              paddingTop: '5%',
              width: '90%',
            },
            dimensions.width
          )}
        >
          {/* app-logo */}
          <Image
            resizeMode={'contain'}
            source={imageSource(Images['DigiSSTransp'])}
            style={StyleSheet.applyWidth(
              { height: 100, marginTop: 40, overflow: 'hidden', width: 300 },
              dimensions.width
            )}
          />
          <View
            style={StyleSheet.applyWidth(
              {
                alignContent: 'center',
                alignItems: 'center',
                backgroundColor: palettes['App Modern'].VeryLight,
                borderRadius: 10,
                marginBottom: 20,
                marginTop: 20,
                paddingBottom: 10,
                paddingLeft: 10,
                paddingRight: 10,
                paddingTop: 10,
              },
              dimensions.width
            )}
          >
            <Text
              accessible={true}
              selectable={false}
              style={StyleSheet.applyWidth(
                {
                  color: theme.colors.branding.primary,
                  fontFamily: 'System',
                  fontWeight: '400',
                  textAlign: 'center',
                },
                dimensions.width
              )}
            >
              {
                'Por razones de seguridad se te ha solicitado crear una nueva contraseña.\n\nMíinimo de 8 caracteres, mayúsculas, minúsculas, caracteres especiales o números'
              }
            </Text>
          </View>
        </View>

        <Container
          backgroundImageResizeMode={'cover'}
          elevation={0}
          useThemeGutterPadding={false}
          style={StyleSheet.applyWidth(
            { alignSelf: 'center', width: '90%' },
            dimensions.width
          )}
        >
          <View
            style={StyleSheet.applyWidth(
              { marginLeft: '2%', marginRight: '2%' },
              dimensions.width
            )}
          >
            <View>
              <View>
                {/* Password */}
                <TextField
                  activeBorderColor={theme.colors.branding.primary}
                  autoCapitalize={'none'}
                  autoCorrect={true}
                  changeTextDelay={500}
                  onChangeText={newPasswordValue => {
                    try {
                      setPassword(newPasswordValue);
                    } catch (err) {
                      console.error(err);
                    }
                  }}
                  type={'solid'}
                  underlineColor={theme.colors.text.light}
                  webShowOutline={true}
                  editable={true}
                  keyboardType={'visible-password'}
                  label={'Nueva contraseña'}
                  placeholder={''}
                  secureTextEntry={true}
                  style={StyleSheet.applyWidth(
                    { marginTop: '1%' },
                    dimensions.width
                  )}
                  value={password}
                />
                <View
                  style={StyleSheet.applyWidth(
                    { justifyContent: 'center', width: 0 },
                    dimensions.width
                  )}
                >
                  <>
                    {!false ? null : (
                      <IconButton
                        icon={'Ionicons/help-circle-outline'}
                        size={24}
                      />
                    )}
                  </>
                </View>
              </View>
            </View>
            <>
              {!SHOW_PASSWORD_ERROR ? null : (
                <Text
                  accessible={true}
                  selectable={false}
                  numberOfLines={2}
                  style={StyleSheet.applyWidth(
                    {
                      color: theme.colors.background.danger,
                      fontSize: 10,
                      marginBottom: 1,
                      textAlign: 'center',
                    },
                    dimensions.width
                  )}
                >
                  {'De 8 a 100 cars,  1 mayúscula, 1 minúscula, 2 dígitos'}
                </Text>
              )}
            </>
            <View>
              {/* PasswordCopy */}
              <TextField
                activeBorderColor={theme.colors.branding.primary}
                autoCapitalize={'none'}
                autoCorrect={true}
                changeTextDelay={500}
                onChangeText={newPasswordCopyValue => {
                  try {
                    setPassword_copy(newPasswordCopyValue);
                  } catch (err) {
                    console.error(err);
                  }
                }}
                type={'solid'}
                underlineColor={theme.colors.text.light}
                webShowOutline={true}
                editable={true}
                keyboardType={'visible-password'}
                label={'Repetir contraseña'}
                placeholder={''}
                secureTextEntry={true}
                style={StyleSheet.applyWidth(
                  { marginBottom: '1%', marginTop: '1%' },
                  dimensions.width
                )}
                value={password_copy}
              />
              <>
                {!SHOW_PASSWORD_MISMATCH_ERROR ? null : (
                  <Text
                    accessible={true}
                    selectable={false}
                    numberOfLines={1}
                    style={StyleSheet.applyWidth(
                      {
                        color: theme.colors.background.danger,
                        fontSize: 10,
                        marginBottom: 1,
                        textAlign: 'center',
                      },
                      dimensions.width
                    )}
                  >
                    {'Las contraseñas no coinciden'}
                  </Text>
                )}
              </>
            </View>
          </View>

          <View
            style={StyleSheet.applyWidth({ marginTop: '4%' }, dimensions.width)}
          >
            <>
              {!errorMessage?.length ? null : (
                <Text
                  accessible={true}
                  selectable={false}
                  style={StyleSheet.applyWidth(
                    {
                      color: theme.colors.background.danger,
                      fontSize: 12,
                      textAlign: 'center',
                    },
                    dimensions.width
                  )}
                >
                  {errorMessage}
                </Text>
              )}
            </>
          </View>
        </Container>

        <View
          style={StyleSheet.applyWidth(
            {
              alignItems: 'center',
              justifyContent: 'flex-end',
              marginBottom: '10%',
              marginTop: '5%',
              paddingLeft: '6%',
              paddingRight: '6%',
            },
            dimensions.width
          )}
        >
          <Touchable
            onPress={() => {
              try {
                if (
                  props.route?.params?.selfChanged ??
                  defaultProps.selfChanged
                ) {
                  navigation.navigate('Main', { screen: 'InicioScreen' });
                } else {
                  navigation.navigate('Permissions', {
                    screen: 'BienvenidoScreen',
                  });
                }
              } catch (err) {
                console.error(err);
              }
            }}
          >
            <Text
              accessible={true}
              selectable={false}
              style={StyleSheet.applyWidth(
                {
                  color: theme.colors.branding.secondary,
                  paddingBottom: '10%',
                  textDecorationLine: 'underline',
                },
                dimensions.width
              )}
            >
              {'Cambiar mas tarde'}
            </Text>
          </Touchable>
          {/* Button Solid */}
          <Button
            iconPosition={'left'}
            onPress={() => {
              const handler = async () => {
                try {
                  if (passwordCheck(password)) {
                    return;
                  }
                  if (passwordCopyCheck(password_copy, password)) {
                    return;
                  }
                  setLoading(true);
                  (
                    await dcSSCambioClavePATCH.mutateAsync({
                      email: Constants['my_emp_email'],
                      new_password: passEncrypt(password),
                    })
                  )?.json;
                  (
                    await dcSSEmployeeTokenPATCH.mutateAsync({
                      emp_id: Constants['my_emp_id'],
                      emp_token: '',
                    })
                  )?.json;
                  setGlobalVariableValue({
                    key: 'AUTH_HEADER',
                    value: '',
                  });
                  setLoading(false);
                  if (navigation.canGoBack()) {
                    navigation.popToTop();
                  }
                  navigation.replace('Auth', { screen: 'IniciarSesionScreen' });
                } catch (err) {
                  console.error(err);
                }
              };
              handler();
            }}
            style={StyleSheet.applyWidth(
              {
                backgroundColor: theme.colors.branding.primary,
                borderRadius: 10,
                color: theme.colors.background.brand,
                fontFamily: 'System',
                fontWeight: '700',
                marginLeft: '6%',
                marginRight: '6%',
                marginTop: '5%',
                minHeight: 48,
                textAlign: 'center',
                width: '100%',
              },
              dimensions.width
            )}
            title={'Cambiar contraseña'}
          />
        </View>
      </KeyboardAwareScrollView>
    </ScreenContainer>
  );
};

export default withTheme(CambioContrasenaScreen);
