import { Platform } from 'react-native';
import * as FileSystem from 'expo-file-system';
import * as Sharing from 'expo-sharing';
import * as IntentLauncher from 'expo-intent-launcher';

const ShareAsync = async res => {
  // console.log('FileOpen.ViewAsync');
  // console.log(res?.uri?.slice(0, 100));

  const mimeType = /data:(.*);/.exec(res?.uri)[1];
  const base64p = res?.uri?.search('base64');
  const base64 = res?.uri?.slice(base64p + 7);

  // console.log(`Sharing.isAvailableAsync(): ${await Sharing.isAvailableAsync()}`);
  // console.log(`mimeType: ${mimeType}, data: ${base64.slice(0, 16)}...`);

  if (Platform.OS !== 'web') {
    // Web no soporta FileSystem
    const fileUri =
      FileSystem.documentDirectory + `${encodeURI('adjunto')}.pdf`;
    // FileSystem.cacheDirectory

    await FileSystem.writeAsStringAsync(fileUri, base64, {
      encoding: FileSystem.EncodingType.Base64,
    });

    if (Platform.OS === 'ios') {
      Sharing.shareAsync(fileUri, {
        // UTI: mimetype,
        dialogTitle: 'Abrir con',
        mimeType: mimeType, // Android
      });
    } else if (Platform.OS === 'android') {
      FileSystem.getContentUriAsync(fileUri).then(cUri => {
        // console.log(cUri);
        IntentLauncher.startActivityAsync('android.intent.action.VIEW', {
          data: cUri,
          flags: 1,
          type: mimeType,
        });
      });
    }
  } else {
    // Web
    let pdfWindow = window.open('', '_blank', 'popup,width=320');
    pdfWindow.document.write(
      "<iframe width='100%' height='100%' src='" +
        encodeURI(res.uri) +
        "'></iframe>"
    );
  }
};

export default ShareAsync;
