const cleanHeaders = headers =>
  Object.fromEntries(Object.entries(headers).filter(kv => kv[1] != null));

export const cambioClavePATCH = async (
  Constants,
  { email, new_password },
  handlers = {}
) => {
  const url = `https://dcss-api.herokuapp.com/changeUser`;
  const options = {
    body: JSON.stringify({
      email: email,
      password: new_password,
      must_change_password: false,
    }),
    headers: cleanHeaders({
      Accept: 'application/json',
      Authorization: Constants['AUTH_HEADER'],
      'Content-Type': 'application/json',
    }),
    method: 'PATCH',
  };
  const res = await fetch(url, options);
  return handleResponse(res, handlers);
};

export const useCambioClavePATCH = (
  initialArgs = {},
  { handlers = {} } = {}
) => {
  const queryClient = useQueryClient();
  const Constants = GlobalVariables.useValues();
  return useMutation(
    args => cambioClavePATCH(Constants, { ...initialArgs, ...args }, handlers),
    {
      onError: (err, variables, { previousValue }) => {
        if (previousValue) {
          return queryClient.setQueryData('employeePassword', previousValue);
        }
      },
      onSettled: () => {
        queryClient.invalidateQueries('employeePassword');
        queryClient.invalidateQueries('employeePasswords');
      },
    }
  );
};

