import * as Draftbit from '../custom-files/Draftbit';

const UpdateConceptsNReasons = async (
  Variables,
  setGlobalVariableValue,
  forceRefresh
) => {
  const reasonsList = Variables['ReasonsList'];
  const conceptsList = Variables['ConceptsList'];

  // console.log(`UpdateConceptsNReasons(forceRefresh: ${forceRefresh})`)

  const empId = Variables['my_emp_id'];

  if (conceptsList.length == 0 || forceRefresh) {
    const conceptsResponse = (
      await Draftbit.DcSSApi.conceptsByEmpGET(Variables, {
        emp_id: empId,
      })
    )?.json;
    if (!conceptsResponse.error) {
      setGlobalVariableValue({
        key: 'ConceptsList',
        value: conceptsResponse,
      });
      // console.log(`releidos ${conceptsResponse.length} conceptos`);
      // console.log(conceptsResponse);
    }
  }
  // console.log(`ConceptsList: ${JSON.stringify(Variables['ConceptsList'], undefined, 2)})`);

  if (reasonsList.length == 0 || forceRefresh) {
    const reasonsResponse = (
      await Draftbit.DcSSApi.reasonsByEmpGET(Variables, {
        emp_id: empId,
      })
    )?.json;
    if (!reasonsResponse.error) {
      setGlobalVariableValue({
        key: 'ReasonsList',
        value: reasonsResponse,
      });
      // console.log(`releidos ${reasonsResponse.length} motivos`);
      // console.log(reasonsResponse);
    }
  }
  // console.log(`ReasonsList: ${JSON.stringify(Variables['ReasonsList'], undefined, 2)})`);
};

export default UpdateConceptsNReasons;
