import React from 'react';
import {
  Button,
  LinearProgress,
  ScreenContainer,
  withTheme,
} from '@draftbit/ui';
import { useIsFocused } from '@react-navigation/native';
import { Platform, Text, View } from 'react-native';
import * as CustomCode from '../CustomCode';
import * as GlobalStyles from '../GlobalStyles.js';
import * as GlobalVariables from '../config/GlobalVariableContext';
import * as GlobalFunctions from '../custom-files/GlobalFunctions';
import * as QRCode from '../custom-files/QRCode';
import palettes from '../themes/palettes';
import * as Utils from '../utils';
import Breakpoints from '../utils/Breakpoints';
import * as StyleSheet from '../utils/StyleSheet';
import useWindowDimensions from '../utils/useWindowDimensions';

const defaultProps = {
  app: 'dss',
  cc: 1,
  ci: 2,
  d: 'a',
  ex: 20,
  li: 4,
  pb: true,
  sk: 'a$1gn@tur3',
  sl: 16,
  ti: 5,
};

const QrshowparamsScreen = props => {
  const { theme, navigation } = props;
  const dimensions = useWindowDimensions();
  const Constants = GlobalVariables.useValues();
  const Variables = Constants;
  const [QRDate, setQRDate] = React.useState(new Date());
  const [msecTimer, setMsecTimer] = React.useState(0);
  const [params, setParams] = React.useState({});
  const [pbar, setPbar] = React.useState(100);
  const [screenName, setScreenName] = React.useState('');
  const getParams = () => {
    const pparams = props?.route?.params ?? defaultProps;
    // console.log(GlobalFunctions.jlog({pparams}));

    var params = GlobalFunctions.GetLinkingParams(pparams);
    // console.log(GlobalFunctions.jlog({params}));

    setParams({ ...params, pb: GlobalFunctions.ToBool(params?.pb) });
  };

  const pbarPos = () => {
    return Platform.OS === 'ios' ? 200 : 0;
  };
  /* 

  Acceso directo a esta pantalla: dss://QRShowScreen o draftbit//QRShowScreen

  Ver: https://www.branch.io/deep-linking/

  https://www.paradigmadigital.com/dev/deep-links-versiones-ios/

  https://firebase.google.com/support/guides/app-links-universal-links
  
  https://rnfirebase.io/
  https://github.com/invertase/react-native-firebase
  https://firebase.google.com/support/dynamic-links-faq#how_should_i_migrate_from_the_service

  Ver https://medium.com/bumble-tech/universal-links-for-android-and-ios-1ddb1e70cab0


const defaultProps = {
app: 'dss',
cc: null,
ci: null,
d: null,
ex: 20,
pb: false,
sk: 'a$1gn@tur3',
sl: 16,
ti: null,
};    

dss://QrshowScreen
dss://QrshowparamsScreen/:app/:ci/:ti/:cc/:ex/:sk/:sl/:pb/:d/:li

*/

  const variables = CustomCode.useValues(); // to use a global variable
  const setVariable = CustomCode.useSetValue(); // to update or modify the value of a global variable

  // const params = props?.route?.params ?? defaultProps;

  const { ex = 20, pb = false } = params;
  const refreshInterval = ex * 1000;
  const timePrecission = true || pb ? 100 : refreshInterval; // ms

  React.useEffect(() => {
    const interval = setInterval(() => {
      if (true || pb) {
        var newTimer;
        if (msecTimer >= refreshInterval) {
          newTimer = 0;
          setQRDate(new Date());
        } else newTimer = msecTimer + timePrecission;

        setMsecTimer(newTimer);
        setPbar((100 * (refreshInterval - newTimer)) / refreshInterval);
      } else setQRDate(new Date());
    }, timePrecission);

    return () => {
      clearInterval(interval);
    };
    // }, [msecTimer, QRDate]);
    // }, [pbar]);
  });
  const isFocused = useIsFocused();
  React.useEffect(() => {
    try {
      if (!isFocused) {
        return;
      }
      getParams();
    } catch (err) {
      console.error(err);
    }
  }, [isFocused]);

  return (
    <ScreenContainer
      scrollable={false}
      hasSafeArea={true}
      style={StyleSheet.applyWidth(
        { justifyContent: 'flex-start' },
        dimensions.width
      )}
    >
      {/* DigicardHeader */}
      <Utils.CustomCodeErrorBoundary>
        <CustomCode.DigicardScreenHeader
          props={props}
          left={{}}
          right={{}}
          title={screenName}
        />
      </Utils.CustomCodeErrorBoundary>
      <View
        style={StyleSheet.applyWidth(
          { height: '70%', justifyContent: 'center' },
          dimensions.width
        )}
      >
        {/* QRView */}
        <View
          style={StyleSheet.applyWidth(
            {
              justifyContent: 'flex-start',
              marginLeft: 5,
              marginRight: 5,
              marginTop: 25,
            },
            dimensions.width
          )}
        >
          {/* Punch View */}
          <View>
            {/* QRPunch */}
            <Utils.CustomCodeErrorBoundary>
              <QRCode.PunchQR
                props={props}
                padding={10}
                gradient={['red', 'blue']}
                sizePc={100}
                app={GlobalFunctions.UrlDecode((params ?? defaultProps)?.app)}
                screen={'QrpunchScreen'}
                companyId={(params ?? defaultProps)?.ci}
                locationId={(params ?? defaultProps)?.li}
                direction={(params ?? defaultProps)?.d}
                taskId={(params ?? defaultProps)?.ti}
                costId={(params ?? defaultProps)?.cc}
                signKey={GlobalFunctions.UrlDecode(
                  (params ?? defaultProps)?.sk
                )}
                signLength={(params ?? defaultProps)?.sl}
                expires={(params ?? defaultProps)?.ex + 3}
                ts={QRDate}
                height={'100%'}
                RNUrl={true}
              />
            </Utils.CustomCodeErrorBoundary>
          </View>
          {/* Punch View 2 */}
          <View
            style={StyleSheet.applyWidth({ top: pbarPos() }, dimensions.width)}
          >
            <>
              {!params?.pb ? null : (
                <LinearProgress
                  animationDuration={500}
                  indeterminate={false}
                  showTrack={true}
                  thickness={10}
                  trackColor={theme.colors.border.brand}
                  color={theme.colors.branding.secondary}
                  isAnimated={false}
                  lineCap={'square'}
                  maximumValue={100}
                  minimumValue={0}
                  trackLineCap={'square'}
                  value={pbar}
                />
              )}
            </>
          </View>
        </View>
      </View>
    </ScreenContainer>
  );
};

export default withTheme(QrshowparamsScreen);
